//! Executes declarative REST integrations described in `integrations.json`
//! (generated by tools/gen_integrations.py).

use super::{Ctx, Out, description};
use crate::model::*;
use anyhow::{Result, anyhow};
use base64::Engine as _;
use serde_json::{Map, Value, json};
use std::time::Duration;

pub async fn run(ctx: &Ctx<'_>, kind: &str) -> Option<Result<Out>> {
    let decl = description(kind)?.get("declarative")?;
    Some(exec(ctx, decl).await)
}

/// Replaces `{name}` with parameter values and `{cred.x}` with credential fields.
/// Path segments are URL encoded unless written as `{+name}`.
pub(crate) fn fill(tpl: &str, encode: bool, lookup: &mut dyn FnMut(&str) -> Result<String>) -> Result<String> {
    let mut out = String::new();
    let mut rest = tpl;
    while let Some(start) = rest.find('{') {
        out.push_str(&rest[..start]);
        let end = rest[start..].find('}').ok_or_else(|| anyhow!("Unclosed placeholder in {tpl}"))? + start;
        let key = &rest[start + 1..end];
        let (raw, key) = match key.strip_prefix('+') {
            Some(k) => (true, k),
            None => (false, key),
        };
        let v = lookup(key)?;
        out.push_str(&if encode && !raw && !key.starts_with("cred.") { urlencode(&v) } else { v });
        rest = &rest[end + 1..];
    }
    out.push_str(rest);
    Ok(out)
}

fn urlencode(s: &str) -> String {
    s.bytes()
        .map(|b| if b.is_ascii_alphanumeric() || b"-_.~:!".contains(&b) { (b as char).to_string() } else { format!("%{b:02X}") })
        .collect()
}

/// Flattens nested JSON into `a[b][0]=c` pairs (form bodies such as Stripe's).
pub(crate) fn flatten(prefix: &str, v: &Value, out: &mut Vec<(String, String)>) {
    match v {
        Value::Object(m) => m.iter().for_each(|(k, x)| flatten(&if prefix.is_empty() { k.clone() } else { format!("{prefix}[{k}]") }, x, out)),
        Value::Array(a) => a.iter().enumerate().for_each(|(i, x)| flatten(&format!("{prefix}[{i}]"), x, out)),
        Value::Null => {}
        other => out.push((prefix.to_string(), as_str(other))),
    }
}

/// RFC 3986 encoding as AWS expects it (only unreserved characters stay).
pub(crate) fn aws_encode(s: &str) -> String {
    s.bytes()
        .map(|b| if b.is_ascii_alphanumeric() || b"-_.~".contains(&b) { (b as char).to_string() } else { format!("%{b:02X}") })
        .collect()
}

/// AWS Signature Version 4 (header variant) for the credential fields region,
/// accessKeyId, secretAccessKey and the optional sessionToken.
pub(crate) fn sign_v4(req: &mut reqwest::Request, c: &Value, service: &str, now: chrono::DateTime<chrono::Utc>) -> Result<()> {
    use hmac::{Hmac, Mac};
    use sha2::{Digest, Sha256};
    let hmac = |key: &[u8], msg: &str| -> Vec<u8> {
        let mut m = Hmac::<Sha256>::new_from_slice(key).expect("any key length");
        m.update(msg.as_bytes());
        m.finalize().into_bytes().to_vec()
    };
    let region = Some(as_str(&c["region"])).filter(|r| !r.is_empty()).unwrap_or_else(|| "us-east-1".into());
    let amz_date = now.format("%Y%m%dT%H%M%SZ").to_string();
    let date = &amz_date[..8];
    let payload = hex::encode(Sha256::digest(req.body().and_then(|b| b.as_bytes()).unwrap_or_default()));
    let url = req.url().clone();
    let host = match url.port() {
        Some(p) => format!("{}:{p}", url.host_str().unwrap_or_default()),
        None => url.host_str().unwrap_or_default().to_string(),
    };
    let mut signed = vec![("host".to_string(), host), ("x-amz-content-sha256".into(), payload.clone()), ("x-amz-date".into(), amz_date.clone())];
    let token = as_str(&c["sessionToken"]);
    if !token.is_empty() {
        signed.push(("x-amz-security-token".into(), token));
    }
    // Every x-amz-* header the request carries (ACL, tagging, storage class, copy source …) must be signed.
    for (k, v) in req.headers() {
        let k = k.as_str().to_lowercase();
        if k.starts_with("x-amz-") && !signed.iter().any(|(s, _)| *s == k) {
            signed.push((k, v.to_str().unwrap_or_default().to_string()));
        }
    }
    signed.sort();
    // The URL path is already encoded once; every service except S3 wants it encoded twice.
    let uri = if service == "s3" { url.path().to_string() } else { url.path().split('/').map(aws_encode).collect::<Vec<_>>().join("/") };
    let mut q: Vec<(String, String)> = url.query_pairs().map(|(k, v)| (aws_encode(&k), aws_encode(&v))).collect();
    q.sort();
    let query = q.iter().map(|(k, v)| format!("{k}={v}")).collect::<Vec<_>>().join("&");
    let headers: String = signed.iter().map(|(k, v)| format!("{k}:{}\n", v.trim())).collect();
    let names = signed.iter().map(|(k, _)| k.as_str()).collect::<Vec<_>>().join(";");
    let canonical = format!("{}\n{uri}\n{query}\n{headers}\n{names}\n{payload}", req.method());
    let scope = format!("{date}/{region}/{service}/aws4_request");
    let to_sign = format!("AWS4-HMAC-SHA256\n{amz_date}\n{scope}\n{}", hex::encode(Sha256::digest(canonical.as_bytes())));
    let mut key = hmac(format!("AWS4{}", as_str(&c["secretAccessKey"])).as_bytes(), date);
    for part in [region.as_str(), service, "aws4_request"] {
        key = hmac(&key, part);
    }
    let signature = hex::encode(hmac(&key, &to_sign));
    let auth = format!("AWS4-HMAC-SHA256 Credential={}/{scope}, SignedHeaders={names}, Signature={signature}", as_str(&c["accessKeyId"]));
    let h = req.headers_mut();
    for (k, v) in signed.iter().filter(|(k, _)| k != "host") {
        h.insert(reqwest::header::HeaderName::from_bytes(k.as_bytes())?, v.parse()?);
    }
    h.insert(reqwest::header::AUTHORIZATION, auth.parse()?);
    Ok(())
}

fn is_blank(v: &Value) -> bool {
    match v {
        Value::Null => true,
        Value::String(s) => s.trim().is_empty(),
        Value::Object(o) => o.is_empty(),
        _ => false,
    }
}

/// Converts a resolved parameter according to the field kind.
fn convert(v: Value, kind: &str, name: &str) -> Result<Value> {
    // Resource locators ({__rl, mode, value}) send their value.
    let v = match v {
        Value::Object(ref m) if m.contains_key("__rl") => json!(super::rl_value(&v)),
        v => v,
    };
    Ok(match (kind, v) {
        ("csv", Value::Array(a)) => json!(a.iter().map(as_str).collect::<Vec<_>>().join(",")),
        ("base64", v) => json!(base64::engine::general_purpose::STANDARD.encode(as_str(&v))),
        ("json", Value::String(s)) => serde_json::from_str(&s).map_err(|e| anyhow!("'{name}' must be valid JSON: {e}"))?,
        ("list", Value::String(s)) => Value::Array(s.split(',').map(|x| json!(x.trim())).filter(|x| x != "").collect()),
        ("number", v) => as_f64(&v).map(|f| if f.fract() == 0.0 { json!(f as i64) } else { json!(f) }).unwrap_or(v),
        (_, v) => v,
    })
}

/// FLOWWOLF_API_BASE_OVERRIDES="https://api.mollie.com/v2=http://mock/mollie,..." points a fixed API base
/// at a sandbox, proxy or mock (used by the contract tests).
pub(crate) fn rebase(base: String) -> String {
    let rules = std::env::var("FLOWWOLF_API_BASE_OVERRIDES").unwrap_or_default();
    for (from, to) in rules.split(',').filter_map(|r| r.split_once('=')) {
        if let Some(rest) = base.strip_prefix(from.trim()) {
            return format!("{}{rest}", to.trim());
        }
    }
    base
}

async fn exec(ctx: &Ctx<'_>, d: &Value) -> Result<Out> {
    let cred_kind = d["credential"].as_str().unwrap_or("");
    // OAuth credentials also carry plain fields (instance URL, region, tenant) that paths and headers use.
    let creds = if cred_kind.is_empty() { json!({}) } else { crate::oauth::with_defaults(cred_kind, &ctx.creds(cred_kind)?) };
    let ops = &d["operations"];
    let mut out = vec![];
    for (i, item) in ctx.items().iter().enumerate() {
        let key = format!("{}:{}", ctx.s("resource", i, "")?, ctx.s("operation", i, "")?);
        let op = ops.get(&key).ok_or_else(|| anyhow!("Operation \"{key}\" is not supported"))?;
        let fields: Vec<Value> = op["fields"].as_array().cloned().unwrap_or_default();
        let kind_of = |name: &str| fields.iter().find(|f| f["name"] == name).and_then(|f| f["kind"].as_str()).unwrap_or("string").to_string();

        let mut lookup = |k: &str| -> Result<String> {
            if let Some(c) = k.strip_prefix("cred.") {
                // "{cred.baseUrl|https://...}" falls back to the text after the bar.
                let (c, fallback) = c.split_once('|').unwrap_or((c, ""));
                let v = as_str(&creds[c]);
                return Ok(if v.is_empty() { fallback } else { &v }.trim_end_matches('/').to_string());
            }
            let v = ctx.s(k, i, "")?;
            if v.is_empty() {
                return Err(anyhow!("Parameter '{k}' is required"));
            }
            Ok(v)
        };
        let base = rebase(fill(d["baseUrl"].as_str().unwrap_or(""), false, &mut lookup)?);
        let path = fill(op["path"].as_str().unwrap_or(""), true, &mut lookup)?;
        let method = op["method"].as_str().unwrap_or("GET").to_string();
        let mut query: Vec<(String, String)> = vec![];
        let mut body = json!({});

        for f in &fields {
            let (name, api, place) = (as_str(&f["name"]), as_str(&f["api"]), f["where"].as_str().unwrap_or("body"));
            if place == "path" || place == "none" {
                continue;
            }
            let Some(v) = ctx.get(&name, i)?.filter(|v| !is_blank(v)) else { continue };
            let mut v = convert(v, &kind_of(&name), &name)?;
            // Option values the API spells differently (e.g. "private" -> is_private: true).
            if let Some(m) = f["map"].as_object() {
                v = m.get(&as_str(&v)).cloned().unwrap_or(v);
            }
            if place == "query" {
                query.push((api, match &v { Value::Array(a) => a.iter().map(as_str).collect::<Vec<_>>().join(","), v => as_str(v) }));
            } else {
                set_path(&mut body, &api, v);
            }
        }
        // Additional fields go to the query for GET and into the body (or a sub object) otherwise.
        let extras: Vec<Value> = op["extra"].as_array().cloned().unwrap_or_default();
        if let Some(Value::Object(af)) = ctx.get(op["extraName"].as_str().unwrap_or("additionalFields"), i)? {
            for (k, v) in af {
                if is_blank(&v) {
                    continue;
                }
                let spec = extras.iter().find(|e| e["name"] == k.as_str());
                let api = spec.map(|e| as_str(&e["api"])).unwrap_or(k.clone());
                let v = convert(v, spec.and_then(|e| e["kind"].as_str()).unwrap_or("string"), &k)?;
                if method == "GET" || d["bodyType"] == "query" || spec.is_some_and(|e| e["where"] == "query") && method != "POST" {
                    query.push((api, as_str(&v)));
                } else {
                    let target = op["extraTarget"].as_str().map(|t| format!("{t}.{api}")).unwrap_or(api);
                    set_path(&mut body, &target, v);
                }
            }
        }
        if let Some(limit_param) = op["limit"].as_str() {
            if !ctx.b("returnAll", i, false)? {
                query.push((limit_param.into(), (ctx.n("limit", i, 50.0)? as i64).to_string()));
            }
        }
        for (k, v) in op["staticQuery"].as_object().into_iter().flatten() {
            query.push((k.clone(), as_str(v)));
        }
        if let Value::Object(s) = &op["static"] {
            for (k, v) in s {
                body[k.as_str()] = v.clone();
            }
        }
        if let Some(t) = op.get("template") {
            // Template values: "{name}" alone keeps the parameter's type, blanks are dropped.
            let rendered = render(t, &mut |k: &str| -> Result<Value> {
                if let Some(c) = k.strip_prefix("cred.") {
                    return Ok(creds[c].clone());
                }
                Ok(match ctx.get(k, i)? {
                    Some(v) if !is_blank(&v) => convert(v, &kind_of(k), k)?,
                    _ => Value::Null,
                })
            })?;
            if let (Value::Object(b), Value::Object(r)) = (&mut body, rendered) {
                for (k, v) in r {
                    b.entry(k).or_insert(v);
                }
            }
        }
        // A JSON parameter whose keys are merged into the body root (e.g. extra service data).
        if let Some(name) = op["mergeJson"].as_str() {
            if let Some(Value::Object(extra)) = ctx.get(name, i)?.filter(|v| !is_blank(v)).map(|v| convert(v, "json", name)).transpose()? {
                for (k, v) in extra {
                    body[k.as_str()] = v;
                }
            }
        }
        match op["bodyFrom"].as_str() {
            Some("sheetRow") => {
                let cols: Vec<String> = ctx.s("columns", i, "")?.split(',').map(|c| c.trim().to_string()).filter(|c| !c.is_empty()).collect();
                let row: Vec<Value> = match &item.json {
                    Value::Object(m) if cols.is_empty() => m.values().map(|v| json!(as_str(v))).collect(),
                    j => cols.iter().map(|c| json!(get_path(j, c).map(as_str).unwrap_or_default())).collect(),
                };
                body = json!({ "values": [row] });
            }
            Some("gmailRaw") => {
                let ctype = if ctx.s("emailType", i, "text")? == "html" { "text/html" } else { "text/plain" };
                let mime = format!(
                    "To: {}\r\nSubject: =?UTF-8?B?{}?=\r\nMIME-Version: 1.0\r\nContent-Type: {ctype}; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n\r\n{}",
                    ctx.s("sendTo", i, "")?,
                    base64::engine::general_purpose::STANDARD.encode(ctx.s("subject", i, "")?),
                    base64::engine::general_purpose::STANDARD.encode(ctx.s("message", i, "")?)
                );
                body = json!({ "raw": base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(mime) });
            }
            Some("jsonParam") => body = convert(ctx.val("data", i, json!({}))?, "json", "data")?,
            _ => {}
        }
        if op["transform"] == "postgrestFilter" {
            for pair in ctx.s("filter", i, "")?.split('&').filter(|p| !p.is_empty()) {
                let (k, v) = pair.split_once('=').unwrap_or((pair, ""));
                query.push((k.trim().into(), v.trim().into()));
            }
        }

        let mut rb = ctx.eng.app.http.request(reqwest::Method::from_bytes(method.as_bytes())?, format!("{base}{path}")).timeout(Duration::from_secs(120));
        for (k, v) in d["headers"].as_object().into_iter().flatten().chain(op["headers"].as_object().into_iter().flatten()) {
            rb = rb.header(k, fill(&as_str(v), false, &mut lookup)?);
        }
        let mut aws_service = None;
        for a in d["auth"].as_array().into_iter().flatten().filter_map(|a| a.as_str()) {
            let p: Vec<&str> = a.split(':').collect();
            // "=literal" uses the text itself instead of a credential field.
            let c = |k: &str| match k.strip_prefix('=') {
                Some(lit) => lit.to_string(),
                None if k.contains('{') => crate::oauth::fill_fields(k, &creds),
                None => as_str(&creds[k]),
            };
            if matches!(p.as_slice(), ["bearer", f] if c(f).is_empty()) {
                continue;
            }
            rb = match p.as_slice() {
                ["bearer", f] => rb.bearer_auth(c(f)),
                ["basic", u, pw] => rb.basic_auth(c(u), Some(c(pw))),
                ["header", name, f] => rb.header(*name, c(f)),
                ["query", name, f] => rb.query(&[(name.to_string(), c(f))]),
                ["oauth2"] => rb.bearer_auth(ctx.oauth_token(cred_kind).await?),
                // Signed after the request is complete (needs the final URL and body).
                ["aws", service] => {
                    aws_service = Some(service.to_string());
                    rb
                }
                _ => return Err(anyhow!("Unknown auth spec {a}")),
            };
        }
        if !query.is_empty() {
            rb = rb.query(&query);
        }
        // Updating or deleting a file needs its current blob sha (GitHub contents API).
        if op["fetchSha"] == true && body.get("sha").is_none() {
            let mut probe = rb.try_clone().ok_or_else(|| anyhow!("request cannot be repeated"))?.build()?;
            *probe.method_mut() = reqwest::Method::GET;
            if let Some(service) = &aws_service {
                sign_v4(&mut probe, &creds, service, chrono::Utc::now())?;
            }
            let found: Value = ctx.eng.app.http.execute(probe).await?.json().await.unwrap_or_default();
            if let Some(sha) = found["sha"].as_str() {
                body["sha"] = json!(sha);
            }
        }
        let has_body = body.as_object().is_some_and(|o| !o.is_empty()) || body.is_array();
        if method != "GET" && method != "DELETE" || has_body {
            rb = if d["bodyType"] == "form" {
                let mut pairs = vec![];
                flatten("", &body, &mut pairs);
                rb.form(&pairs)
            } else {
                rb.json(&body)
            };
        }
        let mut req = rb.build().map_err(|e| anyhow!("Invalid request: {e}"))?;
        if let Some(service) = &aws_service {
            sign_v4(&mut req, &creds, service, chrono::Utc::now())?;
        }
        let resp = ctx.eng.app.http.execute(req).await.map_err(|e| super::integrations::request_error(&e, Some(120_000)))?;
        let status = resp.status();
        let text = resp.text().await?;
        let parsed: Value = if text.trim().is_empty() { json!({"success": true}) } else { serde_json::from_str(&text).unwrap_or_else(|_| json!({"data": text})) };
        // Slack and Telegram answer errors with HTTP 200 and {"ok": false}.
        if let Some(flag) = d["errorFlag"].as_str() {
            if parsed[flag] == false {
                let msg = ["error", "description"].iter().find_map(|k| parsed[*k].as_str()).unwrap_or("request failed");
                return Err(anyhow!("{} error: {msg}", as_str(&d["service"])));
            }
        }
        if !status.is_success() {
            let msg = ["message", "error.message", "error", "errorMessages.0", "detail"]
                .iter()
                .find_map(|p| get_path(&parsed, p).filter(|v| v.is_string()).map(as_str))
                .unwrap_or_else(|| text.chars().take(300).collect());
            return Err(anyhow!("{} {}: {msg}", status.as_u16(), status.canonical_reason().unwrap_or("")));
        }
        let mut v = match op["root"].as_str() {
            Some(r) => get_path(&parsed, r).cloned().unwrap_or(Value::Array(vec![])),
            None => parsed,
        };
        if op["transform"] == "bigqueryRows" {
            let names: Vec<String> = v["schema"]["fields"].as_array().into_iter().flatten().map(|f| as_str(&f["name"])).collect();
            v = Value::Array(
                v["rows"].as_array().into_iter().flatten()
                    .map(|r| Value::Object(names.iter().zip(r["f"].as_array().into_iter().flatten()).map(|(n, c)| (n.clone(), c["v"].clone())).collect::<Map<_, _>>()))
                    .collect(),
            );
        }
        if op["transform"] == "sheetRows" {
            let rows = v["values"].as_array().cloned().unwrap_or_default();
            let head: Vec<String> = rows.first().and_then(|r| r.as_array()).map(|r| r.iter().map(as_str).collect()).unwrap_or_default();
            v = Value::Array(
                rows.iter()
                    .skip(1)
                    .map(|r| Value::Object(head.iter().enumerate().map(|(c, h)| (h.clone(), r.get(c).cloned().unwrap_or(json!("")))).collect::<Map<_, _>>()))
                    .collect(),
            );
        }
        match v {
            Value::Array(a) => out.extend(a.into_iter().map(|x| Item::paired(if x.is_object() { x } else { json!({ "value": x }) }, i))),
            Value::Object(_) => out.push(Item::paired(v, i)),
            other => out.push(Item::paired(json!({ "data": other }), i)),
        }
    }
    Ok(vec![out])
}

/// Renders a JSON template: strings that are exactly "{name}" take the typed value,
/// other strings get placeholders filled; null results drop the key / array entry.
pub(crate) fn render(t: &Value, get: &mut dyn FnMut(&str) -> Result<Value>) -> Result<Value> {
    Ok(match t {
        Value::String(s) => {
            if let Some(k) = s.strip_prefix('{').and_then(|x| x.strip_suffix('}')).filter(|k| !k.contains('{') && !k.contains(' ')) {
                get(k)?
            } else if s.contains('{') && !s.trim_start().starts_with("mutation") && !s.trim_start().starts_with("query") {
                let mut missing = false;
                let filled = fill(s, false, &mut |k: &str| -> Result<String> {
                    let v = get(k)?;
                    missing |= v.is_null();
                    Ok(as_str(&v))
                })?;
                if missing && filled.trim().is_empty() { Value::Null } else { json!(filled) }
            } else {
                json!(s)
            }
        }
        Value::Array(a) => Value::Array(a.iter().map(|x| render(x, get)).collect::<Result<Vec<_>>>()?.into_iter().filter(|x| !x.is_null()).collect()),
        Value::Object(m) => {
            let mut o = Map::new();
            for (k, v) in m {
                let r = render(v, get)?;
                let empty_obj = r.as_object().is_some_and(|x| x.is_empty()) && !v.as_object().is_some_and(|x| x.is_empty());
                // Keys may be placeholders too ({"{attribute}": {}}); an empty key drops the entry.
                let key = if k.starts_with('{') && k.ends_with('}') { as_str(&render(&json!(k), get)?) } else { k.clone() };
                if !r.is_null() && !empty_obj && !key.is_empty() {
                    o.insert(key, r);
                }
            }
            Value::Object(o)
        }
        other => other.clone(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn aws_signature_v4_matches_the_aws_example() {
        // Example "GET Object" from the AWS S3 SigV4 documentation (header-based auth).
        let mut req = reqwest::Request::new(reqwest::Method::GET, "https://examplebucket.s3.amazonaws.com/test.txt".parse().unwrap());
        req.headers_mut().insert("range", "bytes=0-9".parse().unwrap());
        let creds = json!({"region": "us-east-1", "accessKeyId": "AKIAIOSFODNN7EXAMPLE", "secretAccessKey": "wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY"});
        let now = chrono::DateTime::parse_from_rfc3339("2013-05-24T00:00:00Z").unwrap().with_timezone(&chrono::Utc);
        sign_v4(&mut req, &creds, "s3", now).unwrap();
        // Without the range header in the signed set the AWS example signature differs, so check the parts we control.
        let auth = req.headers()["authorization"].to_str().unwrap().to_string();
        assert!(auth.starts_with("AWS4-HMAC-SHA256 Credential=AKIAIOSFODNN7EXAMPLE/20130524/us-east-1/s3/aws4_request, SignedHeaders=host;x-amz-content-sha256;x-amz-date, Signature="));
        assert_eq!(req.headers()["x-amz-content-sha256"], "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855");
        assert_eq!(aws_encode("a b/ü"), "a%20b%2F%C3%BC");
    }

    #[test]
    fn templates_and_forms() {
        let mut look = |k: &str| -> Result<String> { Ok(if k == "cred.server" { "https://api.x".into() } else { format!("a b/{k}") }) };
        assert_eq!(fill("{cred.server}/repos/{owner}/{+file}", true, &mut look).unwrap(), "https://api.x/repos/a%20b%2Fowner/a b/file");
        let mut pairs = vec![];
        flatten("", &json!({"email": "a@b", "metadata": {"k": 1}}), &mut pairs);
        assert_eq!(pairs, vec![("email".into(), "a@b".into()), ("metadata[k]".into(), "1".into())]);
        assert_eq!(convert(json!("x, y"), "list", "l").unwrap(), json!(["x", "y"]));
        let t = json!({"to": [{"email": "{to}"}], "n": "{n}", "skip": "{none}", "text": "Hi {to}", "q": "query { x }"});
        let r = render(&t, &mut |k: &str| Ok(match k { "to" => json!("a@b"), "n" => json!(3), _ => Value::Null })).unwrap();
        assert_eq!(r, json!({"to": [{"email": "a@b"}], "n": 3, "text": "Hi a@b", "q": "query { x }"}));
    }
}
